/* Fantasminha em CSS: flutua, pisca e muda de cara com o estado (.state-...) */
.corpo {
  position: absolute; left: 51px; top: 34px; width: 90px; height: 106px;
  background: #F4F7FF; border-radius: 45px 45px 12px 12px;
  box-shadow: 0 0 22px #9EC5FF, inset -10px -6px 0 #D6E2FF;
  animation: flutua 2s ease-in-out infinite;
}
.olho {
  position: absolute; top: 36px; width: 14px; height: 20px; background: #1B1B2F; border-radius: 50%;
  animation: pisca 2s linear infinite;
}
.olho.e { left: 22px; }
.olho.d { right: 22px; }
.boca {
  position: absolute; left: 37px; top: 64px; width: 16px; height: 8px;
  border: 3px solid #1B1B2F; border-top: none; border-radius: 0 0 12px 12px;
}
.barra { position: absolute; bottom: -12px; left: 0; width: 90px; height: 24px; display: flex; }
.barra i { flex: 1; height: 24px; background: #F4F7FF; border-radius: 0 0 50% 50%; animation: onda 1s ease-in-out infinite; }
.barra i:nth-child(even) { animation-name: onda2; }
.sombra {
  position: absolute; left: 66px; top: 164px; width: 60px; height: 10px; border-radius: 50%;
  background: rgba(140, 170, 255, .25); animation: sombra 2s ease-in-out infinite;
}
@keyframes flutua { 50% { transform: translateY(-8px); } }
@keyframes pisca { 0%, 88%, 100% { transform: scaleY(1); } 94% { transform: scaleY(.1); } }
@keyframes onda { 50% { transform: translateY(5px); } }
@keyframes onda2 { 0%, 100% { transform: translateY(5px); } 50% { transform: translateY(0); } }
@keyframes sombra { 50% { transform: scaleX(.8); opacity: .6; } }

/* Estados */
.state-starting .corpo, .state-connecting .corpo { animation-duration: 1s; }
.state-connecting .olho { animation: olha 2s ease-in-out infinite; }
@keyframes olha { 25% { transform: translateX(-5px); } 75% { transform: translateX(5px); } }
.state-listening .olho { width: 16px; height: 24px; top: 34px; animation: none; }
.state-listening .boca { left: 40px; width: 10px; height: 10px; border: 3px solid #1B1B2F; border-radius: 50%; }
.state-speaking .boca { animation: fala .5s ease-in-out infinite; }
@keyframes fala { 50% { height: 16px; } }
.state-error .corpo, .state-error .barra i { background: #FFD6D6; }
.state-error .corpo { box-shadow: 0 0 22px #FF6B6B, inset -10px -6px 0 #F5B5B5; }
.state-error .olho { top: 44px; height: 4px; border-radius: 2px; transform: rotate(20deg); animation: none; }
.state-error .olho.d { transform: rotate(-20deg); }
.state-error .boca { top: 70px; border-top: 3px solid #1B1B2F; border-bottom: none; border-radius: 12px 12px 0 0; }
